def verify_answer(candidate):
    c = str(candidate).lower().strip()
    found = False
    for i, (title, sents) in enumerate(CONTEXT, 1):
        for j, s in enumerate(sents):
            if c and c in s.lower():
                print(f"FOUND [{i}] {title} ({j}): {s.strip()}")
                found = True
    if not found:
        print(f"NOT FOUND: '{candidate}'")
        c_words = [w.strip('.,;:!?'"'"'()[]{}') for w in c.split() if len(w) > 2]
        if c_words:
            cands = []
            for i, (title, sents) in enumerate(CONTEXT, 1):
                for j, s in enumerate(sents):
                    s_words = set(w.strip('.,;:!?'"'"'()[]{}').lower() for w in s.split())
                    overlap = sum(1 for w in c_words if w in s_words)
                    if overlap >= 1:
                        cands.append((overlap / len(c_words), i, title, j, s.strip()))
            cands.sort(key=lambda x: -x[0])
            for score, i, title, j, s in cands[:3]:
                print(f"NEAR [{i}] {title} ({j}): {s.strip()}")
